\"use client\";

import { useState } from \"react\";
import { useTranslation } from \"react-i18next\";
import { Button } from \"@/modules/ui/components/button\";
import { toast } from \"@/modules/ui/components/toast\";

interface DownloadMyDataProps {
  userId: string;
}

export const DownloadMyData = ({ userId }: Readonly<DownloadMyDataProps>) => {
  const { t } = useTranslation();
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      const response = await fetch(\"/api/v3/account/download-my-data\", {
        method: \"POST\",
        headers: { \"Content-Type\": \"application/json\" },
        body: JSON.stringify({ userId }),
        cache: \"no-store\",
      });

      if ("'!response.ok) {
        toast.error(t("common.something_went_wrong"));
        return;
      }

      const data = await response.json();
      const blob = new Blob([JSON.stringify(data.data, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "formbricks-account-data.json";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success(t("workspace.settings.profile.download_my_data_success"));
    } catch {
      toast.error(t("common.something_went_wrong"));
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} disabled={isDownloading}>
      {isDownloading ? t("common.downloading") : t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};
ENDOFFILE'

